const $ = id => document.getElementById(id);
const fields = ['q','inicio','fim','segmento','cnae','municipio','regiao','situacao','mei','contato','score_min','lead_status','favorito'];
const profileFields = [...fields];
const stageNames = {novo:'Novo',qualificado:'Qualificado',contatado:'Contatado',negociacao:'Em negociação',convertido:'Convertido',descartado:'Descartado'};
const filterNames = {q:'Busca',inicio:'Desde',fim:'Até',segmento:'Segmento',cnae:'CNAE',municipio:'Município',regiao:'Região',situacao:'Situação',mei:'Tipo',contato:'Contato',score_min:'Potencial',lead_status:'Etapa',favorito:'Favoritos'};
let page=1,total=0,lastItems=[],allOptionsLoaded=false,latestReference='',analyticsView='cnae',latestStats=null;
let profiles={},activeProfileId='geral',activePortfolioProfileId='',portfolioPage=1,portfolioTotal=0,portfolioItems=[],teamProfiles={},activeTeamProfileId='',teamPortfolioView='all',syncPollTimer,monitorPollTimer,lastSyncStatus='',lastMonitorStatus='',toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtCnpj=v=>(v||'').replace(/^([A-Z0-9]{2})([A-Z0-9]{3})([A-Z0-9]{3})([A-Z0-9]{4})([A-Z0-9]{2})$/i,'$1.$2.$3/$4-$5');
const fmtDate=v=>{if(!v)return '—';const [y,m,d]=String(v).slice(0,10).split('-');return y&&m&&d?`${d}/${m}/${y}`:'—'};
const fmtDateTime=v=>{if(!v)return '—';const date=new Date(v);return Number.isNaN(date.valueOf())?fmtDate(v):date.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})};
const fmtPhone=v=>{const n=(v||'').replace(/\D/g,'');return n.length>=10?`(${n.slice(0,2)}) ${n.slice(2,-4)}-${n.slice(-4)}`:(v||'—')};
const ptTitle=v=>String(v??'').toLocaleLowerCase('pt-BR').replace(/(^|[\s-])([a-záàâãéêíóôõúç])/g,(_,s,l)=>s+l.toLocaleUpperCase('pt-BR')).replace(/\b(Da|Das|De|Do|Dos|E)\b/g,w=>w.toLocaleLowerCase('pt-BR'));
const pct=(a,b)=>b?Math.round(a/b*100):0;
function animateMetric(element,value){if(!element)return;const next=Number(value||0),previous=Number(element.dataset.metricValue||0);element.dataset.metricValue=String(next);if(element._metricFrame)cancelAnimationFrame(element._metricFrame);if(matchMedia('(prefers-reduced-motion: reduce)').matches||previous===next){element.textContent=next.toLocaleString('pt-BR');return}const started=performance.now(),duration=560;const tick=now=>{const progress=Math.min(1,(now-started)/duration),eased=1-Math.pow(1-progress,3),current=Math.round(previous+(next-previous)*eased);element.textContent=current.toLocaleString('pt-BR');if(progress<1)element._metricFrame=requestAnimationFrame(tick)};element._metricFrame=requestAnimationFrame(tick)}
const companyCount=n=>`${Number(n||0).toLocaleString('pt-BR')} ${Number(n)===1?'empresa':'empresas'}`;
const companyTag=x=>x.mei?'MEI':'PJ';
const scoreLabel=n=>n>=80?'Alto potencial':n>=60?'Bom potencial':n>=40?'Em desenvolvimento':'Baixo potencial';

async function api(url,options){const response=await fetch(url,options);let body={};try{body=await response.json()}catch{}if(!response.ok)throw new Error(body.erro||body.mensagem||`Falha HTTP ${response.status}`);return body}
function query(withPage=true,keepWorkflow=true){const params=new URLSearchParams();fields.forEach(id=>{if(!keepWorkflow&&(id==='lead_status'||id==='favorito'))return;const element=$(id);if(element?.value)params.set(id,element.value)});if(withPage){params.set('page',page);params.set('size',20)}return params}
async function load(){document.body.classList.add('loading');try{const [companies,stats]=await Promise.all([api('/api/companies?'+query()),api('/api/stats?'+query(false,false))]);total=companies.total;lastItems=companies.items;latestStats=stats;renderSummary(stats,total);renderRows();renderAnalytics(stats);renderPipeline(stats);renderOpportunities(stats.opportunities||{});renderRadar(stats);fillOptions(stats.options||{});updateFilterCount()}catch(error){toast('Não foi possível carregar a base.');console.error(error)}finally{document.body.classList.remove('loading')}}
function renderSummary(stats,resultTotal){const s=stats.summary||{};latestReference=s.base_ultima_data||latestReference;animateMetric($('total'),s.total);animateMetric($('meis'),s.meis);animateMetric($('cities'),s.municipios);animateMetric($('contacts'),s.com_contato);$('segments').textContent=`${s.segmentos||0} categorias`;$('meiShare').textContent=pct(s.meis,s.total)+'%';$('contactShare').textContent=pct(s.com_contato,s.total)+'%';const fresh=fmtDate(s.base_ultima_data||s.ultima_data);$('freshDate').textContent=fresh;$('sideFresh').textContent=(s.base_ultima_data||s.ultima_data)?`Referência ${fresh}`:'Sem registros';const stage=$('lead_status').value,stageLabel=stageNames[stage],count=companyCount(resultTotal);$('resultText').textContent=stageLabel?`${count} na etapa “${stageLabel}”`:`${count} correspondem aos filtros atuais`}
function renderRadar(stats){const summary=stats.summary||{},opportunities=stats.opportunities||{},items=(opportunities.items||[]).slice(0,14);animateMetric($('radarTotal'),summary.total);animateMetric($('radarHot'),opportunities.total);animateMetric($('radarCities'),summary.municipios);const signals=$('radarSignals');if(!signals)return;signals.innerHTML=items.map((item,index)=>{const seed=String(item.cnpj||index).split('').reduce((sum,char)=>sum+char.charCodeAt(0),0),angle=((index*137.5)+(seed%31))*Math.PI/180,radius=17+((seed*7)%26),x=50+Math.cos(angle)*radius,y=50+Math.sin(angle)*radius,size=8+Math.max(0,Number(item.lead_score||80)-80)/5,label=`${item.nome_fantasia||item.razao_social} · ${ptTitle(item.municipio)} · potencial ${item.lead_score}`;return `<button class="radar-signal" data-radar-index="${index}" data-label="${esc(label)}" aria-label="Abrir ${esc(item.nome_fantasia||item.razao_social)}" style="--x:${x.toFixed(2)}%;--y:${y.toFixed(2)}%;--signal-size:${size.toFixed(1)}px;--delay:-${(index*.17).toFixed(2)}s"></button>`}).join('');signals.querySelectorAll('[data-radar-index]').forEach(button=>button.onclick=()=>openDetail(items[+button.dataset.radarIndex]))}
function cnaeText(x){return x.cnae_descricao||x.segmento||'Descrição em sincronização'}
function renderRows(){$('rows').innerHTML=lastItems.map((x,i)=>`<tr data-index="${i}"><td><div class="company-cell"><span class="company-avatar" title="${x.mei?'Microempreendedor individual':'Pessoa jurídica'}">${companyTag(x)}</span><div><strong>${esc(x.nome_fantasia||x.razao_social)}${x.favorito?'<span class="favorite-star">★</span>':''}</strong><small>${esc(x.razao_social)} · ${fmtCnpj(x.cnpj)}</small></div></div></td><td><div class="score"><span class="score-ring" style="--score:${x.lead_score}"><b>${x.lead_score}</b></span><small>${scoreLabel(x.lead_score)}</small></div></td><td><strong class="activity-name">${esc(cnaeText(x))}</strong><small>CNAE ${esc(x.cnae)} · ${esc(x.segmento||'Não classificado')}</small></td><td><strong>${esc(ptTitle(x.municipio))}</strong><small>${esc(x.regiao)}</small></td><td><span class="lead-stage">${esc(stageNames[x.lead_status]||'Novo')}</span></td><td><button class="row-action" aria-label="Ver detalhes">→</button></td></tr>`).join('');$('empty').style.display=lastItems.length?'none':'block';const pages=Math.max(1,Math.ceil(total/20));$('pageInfo').textContent=`${page} / ${pages}`;$('rangeInfo').textContent=total?`Exibindo ${(page-1)*20+1}–${Math.min(page*20,total)} de ${total}`:'Nenhum registro';$('prev').disabled=page===1;$('next').disabled=page>=pages;document.querySelectorAll('#rows tr').forEach(row=>row.onclick=()=>openDetail(lastItems[+row.dataset.index]))}
function renderAnalytics(stats){const byCnae=analyticsView==='cnae',summary=stats.mei_summary||{},cnaes=stats.mei_cnaes||[],groups=stats.mei_groups||[],cities=stats.mei_cities||[],timeline=stats.mei_timeline||[];document.querySelectorAll('[data-analytics-view]').forEach(button=>{const active=button.dataset.analyticsView===analyticsView;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});$('meiAnalyticsTotal').textContent=Number(summary.total||0).toLocaleString('pt-BR');$('meiTopCnae').textContent=cnaes[0]?`${cnaes[0].label} · ${cnaes[0].description||cnaes[0].category}`:'—';$('meiTopCity').textContent=cities[0]?ptTitle(cities[0].label):'—';$('analyticsContext').textContent=byCnae?'Compare as atividades econômicas com maior volume de MEIs dentro da janela e dos filtros territoriais.':'Acompanhe a evolução mensal das aberturas de MEI no recorte selecionado.';$('primaryEyebrow').textContent=byCnae?'ATIVIDADES ECONÔMICAS':'EVOLUÇÃO MEI';$('primaryTitle').textContent=byCnae?'CNAEs com mais MEIs':'Aberturas de MEI por mês';$('primaryLegend').innerHTML='<i></i> '+(byCnae?'Aberturas MEI':'Novos MEIs');if(byCnae)renderCnaeChart(cnaes);else renderTrend(timeline);$('secondaryTitle').textContent='Segmentos de maior abertura';$('segments').textContent=`${groups.length} grupos`;const max=Math.max(1,...groups.map(x=>x.value));$('segmentRanking').innerHTML=groups.length?groups.map((x,i)=>`<button class="rank-row rank-button" data-segment="${esc(x.label)}"><span>${i+1}. ${esc(x.label)}</span><b>${Number(x.value).toLocaleString('pt-BR')}</b><div class="rank-track"><div class="rank-fill" style="width:${x.value/max*100}%"></div></div></button>`).join(''):'<p class="panel-meta">Sem aberturas de MEI no recorte.</p>';document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=()=>{$('segmento').value=button.dataset.segment;$('mei').value='sim';activeProfileId='personalizado';page=1;load();navigateToSection('empresas');toast(`Segmento “${button.dataset.segment}” aplicado`)});$('cityRanking').innerHTML=cities.length?cities.map((x,i)=>`<button class="city-row city-button" data-city="${esc(x.label)}"><span class="city-name"><i>${String(i+1).padStart(2,'0')}</i>${esc(ptTitle(x.label))}</span><b>${Number(x.value).toLocaleString('pt-BR')} <small>MEIs</small></b></button>`).join(''):'<p class="panel-meta">Sem aberturas de MEI no recorte.</p>';document.querySelectorAll('[data-city]').forEach(button=>button.onclick=()=>{$('municipio').value=button.dataset.city;$('mei').value='sim';activeProfileId='personalizado';page=1;load();navigateToSection('empresas');toast(`${ptTitle(button.dataset.city)} aplicado aos MEIs`)})}
function renderCnaeChart(data){const box=$('trendChart');box.classList.add('cnae-mode');if(!data.length){box.innerHTML='<p class="panel-meta">Sem CNAEs de MEI no recorte selecionado.</p>';return}const max=Math.max(1,...data.map(x=>x.value)),base=Number(latestStats?.mei_summary?.total||0);box.innerHTML=`<div class="cnae-ranking">${data.slice(0,8).map((x,i)=>`<button class="cnae-row" data-cnae="${esc(x.label)}"><span class="cnae-position">${String(i+1).padStart(2,'0')}</span><span class="cnae-copy"><strong>${esc(x.description||'Atividade sem descrição')} <em>· ${esc(x.label)}</em></strong><small>${esc(x.category||'Atividade econômica')} · ${pct(x.value,base)}% dos MEIs</small><i><b style="width:${x.value/max*100}%"></b></i></span><em>${Number(x.value).toLocaleString('pt-BR')}</em></button>`).join('')}</div>`;box.querySelectorAll('[data-cnae]').forEach(button=>button.onclick=()=>{$('cnae').value=button.dataset.cnae;$('mei').value='sim';activeProfileId='personalizado';page=1;load();navigateToSection('empresas');toast(`CNAE ${button.dataset.cnae} aplicado aos MEIs`)})}
function renderTrend(data){const box=$('trendChart');box.classList.remove('cnae-mode');if(!data.length){box.innerHTML='<p class="panel-meta">Sem histórico no período.</p>';return}const w=560,h=155,pad=20,max=Math.max(1,...data.map(x=>x.value)),step=data.length>1?(w-pad*2)/(data.length-1):0;const pts=data.map((x,i)=>({x:pad+i*step,y:h-25-(x.value/max)*(h-55),...x}));const line=pts.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ');const area=`${line} L ${pts.at(-1).x},${h-25} L ${pts[0].x},${h-25} Z`;box.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b82043" stop-opacity=".36"/><stop offset="1" stop-color="#4c0c1b" stop-opacity=".01"/></linearGradient></defs>${[.25,.5,.75,1].map(n=>`<line class="grid-line" x1="${pad}" y1="${h-25-(h-55)*n}" x2="${w-pad}" y2="${h-25-(h-55)*n}"/>`).join('')}<path class="area" d="${area}"/><path class="line" d="${line}"/>${pts.map(p=>`<circle class="point" cx="${p.x}" cy="${p.y}" r="4"><title>${p.label}: ${p.value}</title></circle><text class="axis-label" x="${p.x}" y="${h-5}" text-anchor="middle">${formatMonth(p.label)}</text>`).join('')}</svg>`}
function formatMonth(value){if(!value)return '';const [y,m]=value.split('-');return new Date(+y,+m-1,1).toLocaleDateString('pt-BR',{month:'short',year:'2-digit'}).replace('.','')}
function renderPipeline(stats){const counts=Object.fromEntries((stats.pipeline||[]).map(x=>[x.label,x.value])),stages=['novo','qualificado','contatado','negociacao','convertido'],selected=$('lead_status').value;$('pipelineGrid').innerHTML=stages.map(stage=>{const count=Number(counts[stage]||0);return `<article class="stage-card ${stage==='convertido'?'hot':''} ${selected===stage?'selected':''} ${count===0?'empty-stage':''}" data-stage="${stage}" data-count="${count}" role="button" tabindex="0"><span>${stageNames[stage]}</span><strong>${count.toLocaleString('pt-BR')}</strong><small>${stage==='novo'?'Aguardando triagem':stage==='qualificado'?'Perfil validado':stage==='contatado'?'Abordagem iniciada':stage==='negociacao'?'Oportunidade aberta':'Clientes conquistados'}</small></article>`}).join('');$('favoriteCount').textContent=stats.favorites||0;document.querySelectorAll('.stage-card').forEach(card=>{const activate=()=>{const count=Number(card.dataset.count);if(!count){toast(`Nenhuma empresa na etapa “${stageNames[card.dataset.stage]}”`);return}$('lead_status').value=card.dataset.stage;$('favorito').value='';activeProfileId='personalizado';page=1;load();navigateToSection('empresas');toast(`${companyCount(count)} na etapa “${stageNames[card.dataset.stage]}”`)};card.onclick=activate;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}}})}
function renderOpportunities(data){animateMetric($('opportunityTotal'),data.total);animateMetric($('opportunityContact'),data.with_contact);animateMetric($('opportunityMei'),data.mei);const items=data.items||[];$('opportunityGrid').innerHTML=items.length?items.map((x,i)=>`<button class="opportunity-card" data-opportunity="${i}"><span class="opportunity-score"><b>${x.lead_score}</b><small>potencial</small></span><span class="opportunity-copy"><small>${x.mei?'MEI':'EMPRESA'} · ${fmtDate(x.data_abertura)}</small><strong>${esc(x.nome_fantasia||x.razao_social)}</strong><em>${esc(cnaeText(x))}</em><span>${esc(ptTitle(x.municipio))} · ${x.telefone||x.email?'Contato disponível':'Sem contato público'}</span></span><i>→</i></button>`).join(''):'<div class="empty-opportunities"><strong>Nenhum lead atingiu 80 neste recorte</strong><p>Amplie o período ou retire filtros territoriais.</p></div>';document.querySelectorAll('[data-opportunity]').forEach(button=>button.onclick=()=>openDetail(items[+button.dataset.opportunity]))}
function fillOptions(options){if(!allOptionsLoaded){['municipio','regiao','segmento'].forEach(id=>{const select=$(id),current=select.value,label=id==='municipio'?'Todos os municípios':id==='regiao'?'Todas as regiões':'Todos os segmentos';select.innerHTML=`<option value="">${label}</option>`+(options[id]||[]).map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');select.value=current});allOptionsLoaded=true}$('cnaeOptions').innerHTML=(options.cnaes||[]).map(item=>`<option value="${esc(item.codigo)}">${esc(item.descricao||item.segmento||'Atividade econômica')} · ${Number(item.empresas||0).toLocaleString('pt-BR')} empresas</option>`).join('')}
function filterSnapshot(){return Object.fromEntries(profileFields.filter(id=>$(id)?.value).map(id=>[id,$(id).value]))}
function filterBadges(values){const entries=Object.entries(values||{});if(!entries.length)return '<span class="profile-chip">Sem restrições</span>';return entries.map(([key,value])=>`<span class="profile-chip"><b>${esc(filterNames[key]||key)}</b>${esc(profileValue(key,value))}</span>`).join('')}
function profileValue(key,value){if(key==='mei')return value==='sim'?'Apenas MEI':'Não MEI';if(key==='contato')return value==='sim'?'Com contato':'Sem contato';if(key==='favorito')return 'Apenas favoritos';if(key==='score_min')return `${value} ou mais`;if(key==='lead_status')return stageNames[value]||value;if(key==='inicio'||key==='fim')return fmtDate(value);return value}
async function loadProfiles(){try{const data=await api('/api/profiles');profiles=Object.fromEntries(data.items.map(item=>[item.id,item]));renderProfileOptions();renderProfileCards()}catch(error){console.error(error);toast('Não foi possível carregar as segmentações')}}
function renderProfileOptions(){const list=Object.values(profiles);$('profileOptions').innerHTML=list.map((profile,index)=>{const meta=profile.is_system?companyCount(profile.companies):`${Number(profile.lead_count||0).toLocaleString('pt-BR')} ${Number(profile.lead_count||0)===1?'lead selecionado':'leads selecionados'}`;return `<button class="${activeProfileId===profile.id?'active':''}" data-profile="${esc(profile.id)}" role="option" aria-selected="${activeProfileId===profile.id}"><i>${String(index+1).padStart(2,'0')}</i><span><b>${esc(profile.name)}</b><small>${meta}</small></span></button>`}).join('');$('activeProfileName').textContent=profiles[activeProfileId]?.name||(activeProfileId==='personalizado'?'Recorte personalizado':'Visão geral');document.querySelectorAll('#profileOptions [data-profile]').forEach(button=>button.onclick=()=>applyProfile(button.dataset.profile))}
function renderProfileCards(){$('profileCards').innerHTML=Object.values(profiles).map(profile=>`<article class="profile-card ${activeProfileId===profile.id?'active':''}"><div class="profile-card-top"><span>${profile.is_system?'SEGMENTAÇÃO DO RADAR':'SEGMENTAÇÃO PERSONALIZADA'}</span><strong>${companyCount(profile.companies)}</strong></div><h3>${esc(profile.name)}</h3><p>${esc(profile.description||'Filtros comerciais salvos.')}</p><div class="profile-chips">${filterBadges(profile.filters)}</div><div class="profile-card-actions"><button data-use-profile="${esc(profile.id)}">Aplicar segmentação →</button>${profile.is_system?'':`<button class="danger" data-delete-profile="${esc(profile.id)}">Excluir</button>`}</div></article>`).join('');document.querySelectorAll('[data-use-profile]').forEach(button=>button.onclick=()=>{applyProfile(button.dataset.useProfile);navigateToSection('empresas')});document.querySelectorAll('[data-delete-profile]').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir esta segmentação salva?'))return;try{await api('/api/profiles/'+button.dataset.deleteProfile,{method:'DELETE'});if(activeProfileId===button.dataset.deleteProfile)activeProfileId='geral';await loadProfiles();toast('Segmentação excluída')}catch(error){toast(error.message)}})}
function applyProfile(id,loadNow=true){const profile=profiles[id];if(!profile)return;profileFields.forEach(key=>{if($(key))$(key).value=''});Object.entries(profile.filters||{}).forEach(([key,value])=>{if($(key))$(key).value=value});activeProfileId=id;localStorage.setItem('radar-profile',id);page=1;renderProfileOptions();renderProfileCards();if(loadNow)load();toast(`Perfil “${profile.name}” ativado`)}
function markCustom(){activeProfileId='personalizado';renderProfileOptions();renderProfileCards()}
function openProfileModal(){$('profileName').value='';$('profileDescription').value='';$('profileFilterPreview').innerHTML=filterBadges(filterSnapshot());openLayer('profile');setTimeout(()=>$('profileName').focus(),80)}
async function saveProfile(){const name=$('profileName').value.trim();if(!name){toast('Informe um nome para a segmentação');$('profileName').focus();return}try{const created=await api('/api/profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,description:$('profileDescription').value.trim(),filters:filterSnapshot()})});closeLayers();await loadProfiles();applyProfile(created.id);navigateToSection('segmentacoes');toast(`Segmentação “${created.name||name}” criada`)}catch(error){toast(error.message)}}
function updateFilterCount(){const n=['segmento','cnae','municipio','regiao','situacao','mei','contato','score_min','lead_status','favorito'].filter(id=>$(id).value).length;$('filterCount').textContent=n;if($('filterCountInline'))$('filterCountInline').textContent=n;document.querySelectorAll('#filterToggle,#companyFilterToggle').forEach(button=>button.classList.toggle('has-filters',n>0));renderProfileOptions()}
function setFilterDrawer(open){const drawer=$('filterDrawer');drawer.classList.toggle('open',open);document.body.classList.toggle('filters-open',open);document.querySelectorAll('#filterToggle,#companyFilterToggle').forEach(button=>button.setAttribute('aria-expanded',String(open)));if(open){navigateToSection('empresas');requestAnimationFrame(()=>requestAnimationFrame(()=>drawer.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})))}else document.querySelector('#empresas .section-head')?.scrollIntoView({behavior:'auto',block:'start'})}
function customProfiles(){return Object.values(profiles).filter(profile=>!profile.is_system)}
function initials(name){return String(name||'').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'R'}
async function loadTeamProfiles(){try{const data=await api('/api/team-profiles');teamProfiles=Object.fromEntries((data.items||[]).map(item=>[item.id,item]));if(!teamProfiles[activeTeamProfileId])activeTeamProfileId=Object.keys(teamProfiles)[0]||'';renderTeamProfileCards();renderPortfolioProfiles();if(activeTeamProfileId)loadPortfolio()}catch(error){console.error(error);toast('Não foi possível carregar os perfis individuais')}}
function renderTeamProfileCards(){const box=$('teamProfileGrid');if(!box)return;const list=Object.values(teamProfiles);box.innerHTML=list.length?list.map(profile=>`<article class="team-profile-card ${activeTeamProfileId===profile.id?'active':''}"><div class="team-profile-card-head"><span class="team-profile-avatar">${esc(profile.initials||initials(profile.name))}</span><span><strong>${esc(profile.name)}</strong><small>${esc(profile.role||'Vendedor')}</small></span><button class="team-profile-star" title="Favoritos na carteira">★ ${Number(profile.favorite_count||0).toLocaleString('pt-BR')}</button></div><div class="team-profile-stats"><span><b>${Number(profile.lead_count||0).toLocaleString('pt-BR')}</b> leads na carteira</span><span>${profile.last_activity?`Atividade ${fmtDateTime(profile.last_activity)}`:'Ainda sem atividade'}</span></div><div class="team-profile-card-actions"><button data-open-team-profile="${esc(profile.id)}">Abrir espaço de trabalho →</button><button class="danger" data-delete-team-profile="${esc(profile.id)}">Excluir</button></div></article>`).join(''):'<div class="team-profile-empty"><strong>Nenhum perfil individual criado</strong><p>Crie o primeiro usuário para começar a distribuir e trabalhar seus leads.</p></div>';box.querySelectorAll('[data-open-team-profile]').forEach(button=>button.onclick=()=>openTeamPortfolio(button.dataset.openTeamProfile));box.querySelectorAll('[data-delete-team-profile]').forEach(button=>button.onclick=()=>deleteTeamProfile(button.dataset.deleteTeamProfile))}
function renderPortfolioProfiles(){const box=$('portfolioProfiles');if(!box)return;const list=Object.values(teamProfiles);$('portfolioProfileCount').textContent=list.length;box.innerHTML=list.length?list.map((profile,index)=>`<button class="portfolio-profile ${activeTeamProfileId===profile.id?'active':''}" data-team-portfolio-profile="${esc(profile.id)}"><span class="portfolio-profile-mark">${esc(profile.initials||String(index+1).padStart(2,'0'))}</span><span class="portfolio-profile-copy"><strong>${esc(profile.name)}</strong><small>${Number(profile.lead_count||0).toLocaleString('pt-BR')} ${Number(profile.lead_count||0)===1?'lead':'leads'}</small></span><b class="portfolio-profile-count">${Number(profile.favorite_count||0).toLocaleString('pt-BR')} ★</b></button>`).join(''):'<div class="portfolio-empty-small"><strong>Nenhum perfil individual</strong><p>Crie um usuário para organizar carteiras separadas.</p></div>';box.querySelectorAll('[data-team-portfolio-profile]').forEach(button=>button.onclick=()=>openTeamPortfolio(button.dataset.teamPortfolioProfile))}
function openTeamPortfolio(profileId){activeTeamProfileId=profileId;portfolioPage=1;teamPortfolioView='all';renderTeamProfileCards();renderPortfolioProfiles();loadPortfolio();navigateToSection('carteiras')}
async function loadPortfolio(){const profile=teamProfiles[activeTeamProfileId];if(!profile){portfolioItems=[];portfolioTotal=0;renderPortfolioLeads();return}try{const data=await api(`/api/team-leads?profile_id=${encodeURIComponent(activeTeamProfileId)}&view=${encodeURIComponent(teamPortfolioView)}&page=${portfolioPage}&size=24`);portfolioItems=data.items||[];portfolioTotal=Number(data.total||0);renderPortfolioLeads()}catch(error){console.error(error);toast('Não foi possível carregar esta carteira')}}
function renderPortfolioLeads(){const box=$('portfolioLeads');if(!box)return;const profile=teamProfiles[activeTeamProfileId],empty=$('portfolioEmpty'),pager=$('portfolioPager');if(!profile){$('portfolioTitle').textContent='Selecione um perfil';$('portfolioMeta').textContent='Crie um perfil individual para começar a separar leads.';box.innerHTML='';empty.hidden=false;if(pager)pager.hidden=true;return}$('portfolioTitle').textContent=profile.name;$('portfolioMeta').textContent=`${Number(portfolioTotal).toLocaleString('pt-BR')} ${portfolioTotal===1?'lead':'leads'} · ${profile.role||'Vendedor'}${teamPortfolioView==='favorites'?' · somente favoritos':''}`;empty.hidden=portfolioItems.length>0;box.innerHTML=portfolioItems.map((x,i)=>`<article class="portfolio-lead ${x.profile_favorito?'is-favorite':''}"><div class="portfolio-lead-top"><span>${x.mei?'MEI':'PJ'} · ${fmtDate(x.data_abertura)}</span><button class="portfolio-star ${x.profile_favorito?'active':''}" data-team-favorite="${esc(x.cnpj)}" title="${x.profile_favorito?'Remover favorito':'Favoritar lead'}">★</button><b>${x.lead_score}</b></div><h4>${esc(x.nome_fantasia||x.razao_social)}</h4><span class="portfolio-lead-meta">${esc(fmtCnpj(x.cnpj))} · ${esc(x.razao_social)}</span><strong class="portfolio-lead-activity">${esc(cnaeText(x))}</strong><span class="portfolio-lead-location">${esc(ptTitle(x.municipio))} · ${esc(x.regiao||'RS')}</span><span class="portfolio-lead-stage">${esc(stageNames[x.profile_lead_status]||'Novo')}</span>${x.profile_estrategia?`<p class="portfolio-lead-note"><b>Estratégia:</b> ${esc(x.profile_estrategia)}</p>`:''}<div class="portfolio-lead-actions"><button data-portfolio-open="${i}">Abrir ficha →</button><button class="remove" data-portfolio-remove="${esc(x.cnpj)}">Remover</button></div></article>`).join('');const pages=Math.max(1,Math.ceil(portfolioTotal/24));$('portfolioRange').textContent=portfolioTotal?`Exibindo ${(portfolioPage-1)*24+1}–${Math.min(portfolioPage*24,portfolioTotal)} de ${portfolioTotal}`:'Nenhum lead selecionado';$('portfolioPageInfo').textContent=`Página ${portfolioPage} / ${pages}`;$('portfolioPrev').disabled=page===1;$('portfolioNext').disabled=portfolioPage>=pages;if(pager)pager.hidden=portfolioTotal===0;box.querySelectorAll('[data-portfolio-open]').forEach(button=>button.onclick=()=>openDetail(portfolioItems[+button.dataset.portfolioOpen]));box.querySelectorAll('[data-portfolio-remove]').forEach(button=>button.onclick=()=>removeLeadFromPortfolio(button.dataset.portfolioRemove));box.querySelectorAll('[data-team-favorite]').forEach(button=>button.onclick=()=>toggleTeamFavorite(button.dataset.teamFavorite,button.classList.contains('active')))}
async function removeLeadFromPortfolio(cnpj){if(!activeTeamProfileId)return;try{await api(`/api/team-leads?profile_id=${encodeURIComponent(activeTeamProfileId)}&cnpj=${encodeURIComponent(cnpj)}`,{method:'DELETE'});await loadTeamProfiles();toast('Lead removido da carteira')}catch(error){toast(error.message)}}
async function addLeadToPortfolio(cnpj){const profileId=$('detailTeamProfile')?.value||activeTeamProfileId;if(!profileId){toast('Crie um perfil individual primeiro');return}try{const result=await api('/api/team-leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:profileId,cnpj})});activeTeamProfileId=profileId;await loadTeamProfiles();await loadDetailMemberships(cnpj);toast(result.adicionado?'Lead adicionado à carteira':'Este lead já está na carteira')}catch(error){toast(error.message)}}
async function toggleTeamFavorite(cnpj,current){try{await api('/api/team-leads',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:activeTeamProfileId,cnpj,favorito:!current})});await loadTeamProfiles();toast(current?'Lead removido dos favoritos':'Lead favoritado')}catch(error){toast(error.message)}}
async function loadDetailMemberships(cnpj){const box=$('detailTeamMemberships');if(!box)return;try{const data=await api(`/api/team-memberships?cnpj=${encodeURIComponent(cnpj)}`);const memberships=data.items||[];box.innerHTML=memberships.filter(x=>x.selected).map(x=>`<span>${esc(x.name)}${x.favorito?' ★':''}</span>`).join('')||'<small>Este lead ainda não está em nenhuma carteira.</small>';const selected=memberships.find(x=>x.id===activeTeamProfileId&&x.selected)||memberships.find(x=>x.selected);if(selected){$('detailTeamProfile').value=selected.id;$('teamLeadStage').value=selected.lead_status||'novo';$('teamFavoriteBtn').classList.toggle('active',Boolean(selected.favorito));$('teamNotes').value=selected.observacoes||'';$('teamStrategy').value=selected.estrategia||'';$('teamLeadSave').disabled=false}else{$('teamLeadSave').disabled=true}}catch(error){console.warn(error)}}
function openDetail(x){const source=x.data_source||'Receita Federal',custom=customProfiles();$('detailContent').innerHTML=`<div class="detail-hero"><span class="company-avatar">${companyTag(x)}</span>${x.mei?'':`<span class="badge">${esc(x.porte||'Empresa')}</span>`}<h2>${esc(x.nome_fantasia||x.razao_social)}</h2><p>${esc(x.razao_social)}</p><span class="status">${esc(x.situacao)}</span></div><div class="detail-leadbox"><div class="score"><div><strong>Potencial comercial</strong><p class="score-explain">Índice de acionabilidade baseado em recência, situação ativa e completude dos dados públicos; não representa intenção de compra.</p></div><span class="score-ring" style="--score:${x.lead_score}"><b>${x.lead_score}</b></span></div><div class="lead-actions"><select id="detailStage" aria-label="Etapa comercial">${Object.entries(stageNames).map(([v,n])=>`<option value="${v}" ${x.lead_status===v?'selected':''}>${n}</option>`).join('')}</select><button class="favorite-btn ${x.favorito?'active':''}" id="favoriteBtn" title="Favoritar">★</button></div></div><section class="detail-section"><h3>CADASTRO E ATIVIDADE</h3><div class="detail-grid"><div class="detail-item"><span>CNPJ</span><strong>${fmtCnpj(x.cnpj)}</strong></div><div class="detail-item"><span>Início da atividade</span><strong>${fmtDate(x.data_abertura)}</strong></div><div class="detail-item detail-wide"><span>CNAE principal · ${esc(x.cnae||'—')}</span><strong>${esc(cnaeText(x))}</strong></div><div class="detail-item"><span>Segmento econômico</span><strong>${esc(x.segmento||'—')}</strong></div><div class="detail-item"><span>Tipo e porte</span><strong>${x.mei?'Microempreendedor individual':esc(x.porte||'Pessoa jurídica')}</strong></div>${x.cnaes_secundarios?`<div class="detail-item detail-wide"><span>CNAEs secundários</span><strong>${esc(x.cnaes_secundarios)}</strong></div>`:''}</div></section><section class="detail-section"><h3>LOCALIZAÇÃO</h3><div class="detail-item"><span>Endereço</span><strong>${esc([x.logradouro,x.numero,x.bairro].filter(Boolean).join(', ')||'—')}</strong></div><div class="detail-grid"><div class="detail-item"><span>Município</span><strong>${esc(ptTitle(x.municipio))} / RS</strong></div><div class="detail-item"><span>CEP</span><strong>${esc(x.cep||'—')}</strong></div></div></section><section class="detail-section"><h3>CONTATO PÚBLICO</h3><div class="detail-grid contact-grid"><div class="detail-item"><span>Telefone</span><strong>${esc(fmtPhone(x.telefone))}</strong></div><div class="detail-item contact-email"><span>Correio eletrônico</span><strong>${esc(x.email||'—')}</strong></div></div></section><section class="detail-section source-audit"><h3>ORIGEM E VALIDAÇÃO</h3><div class="detail-grid"><div class="detail-item"><span>Fonte mais recente</span><strong>${esc(source)}</strong></div><div class="detail-item"><span>Validação Serpro</span><strong>${x.serpro_checked_at?fmtDateTime(x.serpro_checked_at):'Ainda não validado'}</strong></div></div></section><section class="detail-section detail-wallet"><h3>CARTEIRAS DE PROSPECÇÃO</h3><p class="detail-wallet-copy">Escolha um perfil personalizado para manter este lead em foco. A seleção fica salva para toda a equipe.</p><div class="detail-wallet-controls"><select id="detailPortfolio" aria-label="Perfil da carteira"><option value="">${custom.length?'Selecione um perfil':'Crie um perfil personalizado primeiro'}</option>${custom.map(profile=>`<option value="${esc(profile.id)}" ${profile.id===activePortfolioProfileId?'selected':''}>${esc(profile.name)} · ${Number(profile.lead_count||0).toLocaleString('pt-BR')} leads</option>`).join('')}</select><button id="addToPortfolio" ${custom.length?'':'disabled'}>Adicionar lead</button></div>${custom.length?'':'<button class="secondary detail-create-profile" id="detailCreateProfile">Criar perfil personalizado →</button>'}<div class="detail-memberships" id="detailMemberships"><small>Verificando carteiras…</small></div></section><section class="detail-section"><h3>ANOTAÇÕES COMERCIAIS</h3><textarea class="notes" id="leadNotes" placeholder="Registre o contexto, a próxima ação ou o histórico…">${esc(x.observacoes||'')}</textarea><button class="primary save-note" id="saveNote">Salvar anotações</button></section>`;$('detailStage').onchange=e=>saveLead(x,{lead_status:e.target.value},'Etapa atualizada');$('favoriteBtn').onclick=()=>saveLead(x,{favorito:!x.favorito},x.favorito?'Empresa removida dos favoritos':'Empresa adicionada aos favoritos');$('saveNote').onclick=()=>saveLead(x,{observacoes:$('leadNotes').value},'Anotação salva',true);$('addToPortfolio')?.addEventListener('click',()=>addLeadToPortfolio(x.cnpj));$('detailCreateProfile')?.addEventListener('click',openProfileModal);openLayer('detail');loadDetailMemberships(x.cnpj)}
async function saveLead(current,changes,message,closeAfter=false){try{const updated=await api('/api/leads/'+current.cnpj,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(changes)});Object.assign(current,updated);if(closeAfter)closeLayers();toast(message);await load();if(!closeAfter)openDetail(current)}catch{toast('Não foi possível salvar a alteração')}}
function openDetail(x){const source=x.data_source||'Receita Federal',teamList=Object.values(teamProfiles),selectedTeam=teamList.find(p=>p.id===activeTeamProfileId)||teamList[0];if(selectedTeam)activeTeamProfileId=selectedTeam.id;$('detailContent').innerHTML=`<div class="detail-hero"><span class="company-avatar">${companyTag(x)}</span>${x.mei?'':`<span class="badge">${esc(x.porte||'Empresa')}</span>`}<h2>${esc(x.nome_fantasia||x.razao_social)}</h2><p>${esc(x.razao_social)}</p><span class="status">${esc(x.situacao)}</span></div><div class="detail-leadbox"><div class="score"><div><strong>Potencial comercial</strong><p class="score-explain">Índice de acionabilidade baseado em recência, situação ativa e completude dos dados públicos; não representa intenção de compra.</p></div><span class="score-ring" style="--score:${x.lead_score}"><b>${x.lead_score}</b></span></div></div><section class="detail-section"><h3>CADASTRO E ATIVIDADE</h3><div class="detail-grid"><div class="detail-item"><span>CNPJ</span><strong>${fmtCnpj(x.cnpj)}</strong></div><div class="detail-item"><span>Início da atividade</span><strong>${fmtDate(x.data_abertura)}</strong></div><div class="detail-item detail-wide"><span>CNAE principal · ${esc(x.cnae||'—')}</span><strong>${esc(cnaeText(x))}</strong></div><div class="detail-item"><span>Segmento econômico</span><strong>${esc(x.segmento||'—')}</strong></div><div class="detail-item"><span>Tipo e porte</span><strong>${x.mei?'Microempreendedor individual':esc(x.porte||'Pessoa jurídica')}</strong></div>${x.cnaes_secundarios?`<div class="detail-item detail-wide"><span>CNAEs secundários</span><strong>${esc(x.cnaes_secundarios)}</strong></div>`:''}</div></section><section class="detail-section"><h3>LOCALIZAÇÃO</h3><div class="detail-item"><span>Endereço</span><strong>${esc([x.logradouro,x.numero,x.bairro].filter(Boolean).join(', ')||'—')}</strong></div><div class="detail-grid"><div class="detail-item"><span>Município</span><strong>${esc(ptTitle(x.municipio))} / RS</strong></div><div class="detail-item"><span>CEP</span><strong>${esc(x.cep||'—')}</strong></div></div></section><section class="detail-section"><h3>CONTATO PÚBLICO</h3><div class="detail-grid contact-grid"><div class="detail-item"><span>Telefone</span><strong>${esc(fmtPhone(x.telefone))}</strong></div><div class="detail-item contact-email"><span>Correio eletrônico</span><strong>${esc(x.email||'—')}</strong></div></div></section><section class="detail-section source-audit"><h3>ORIGEM E VALIDAÇÃO</h3><div class="detail-grid"><div class="detail-item"><span>Fonte mais recente</span><strong>${esc(source)}</strong></div><div class="detail-item"><span>Validação Serpro</span><strong>${x.serpro_checked_at?fmtDateTime(x.serpro_checked_at):'Ainda não validado'}</strong></div></div></section><section class="detail-section detail-workspace"><div class="workspace-heading"><div><p class="eyebrow">TRABALHO DO LEAD</p><h3>Carteira por perfil</h3></div><span class="workspace-badge">Dados separados por usuário</span></div><p class="detail-wallet-copy">Escolha o perfil responsável. A estrela adiciona o lead à carteira dele e libera o registro de etapa, observações e estratégia.</p><div class="detail-wallet-controls"><select id="detailTeamProfile" aria-label="Perfil individual"><option value="">${teamList.length?'Selecione um perfil':'Crie um perfil individual primeiro'}</option>${teamList.map(profile=>`<option value="${esc(profile.id)}" ${profile.id===activeTeamProfileId?'selected':''}>${esc(profile.name)} · ${esc(profile.role||'Vendedor')}</option>`).join('')}</select><button id="addToTeamPortfolio" ${teamList.length?'':'disabled'}>Adicionar à carteira</button></div>${teamList.length?'':'<button class="secondary detail-create-profile" id="detailCreateTeamProfile">Criar perfil individual →</button>'}<div class="detail-memberships" id="detailTeamMemberships"><small>Verificando carteiras…</small></div><div class="team-lead-editor"><div class="team-editor-head"><strong>Trabalho deste perfil</strong><button class="favorite-btn" id="teamFavoriteBtn" title="Favoritar lead">★</button></div><div class="team-editor-grid"><label>Etapa<select id="teamLeadStage" disabled>${Object.entries(stageNames).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></label><label>Estratégia<textarea id="teamStrategy" maxlength="4000" disabled placeholder="Como abordar este lead, oferta, canal e próxima ação…"></textarea></label><label>Observações<textarea id="teamNotes" maxlength="4000" disabled placeholder="Registre contexto, histórico e retornos…"></textarea></label></div><button class="primary save-note" id="teamLeadSave" disabled>Salvar trabalho do lead</button></div></section>`;$('detailTeamProfile')?.addEventListener('change',e=>{activeTeamProfileId=e.target.value;loadDetailMemberships(x.cnpj)});$('addToTeamPortfolio')?.addEventListener('click',()=>addLeadToPortfolio(x.cnpj));$('detailCreateTeamProfile')?.addEventListener('click',openTeamProfileModal);$('teamFavoriteBtn')?.addEventListener('click',async()=>{if(!$('teamLeadProfileReady')&&!$('teamLeadSave').disabled){await saveTeamLead(x.cnpj,{favorito:!$('teamFavoriteBtn').classList.contains('active')},'Favorito atualizado')}});$('teamLeadSave')?.addEventListener('click',()=>saveTeamLead(x.cnpj,{lead_status:$('teamLeadStage').value,favorito:$('teamFavoriteBtn').classList.contains('active'),observacoes:$('teamNotes').value,estrategia:$('teamStrategy').value},'Trabalho do lead salvo',true));openLayer('detail');loadDetailMemberships(x.cnpj)}
async function saveTeamLead(cnpj,changes,message,closeAfter=false){if(!activeTeamProfileId)return;try{await api('/api/team-leads',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile_id:activeTeamProfileId,cnpj,...changes})});await loadTeamProfiles();if(closeAfter)closeLayers();else loadDetailMemberships(cnpj);toast(message)}catch(error){toast(error.message)}}
function openTeamProfileModal(){$('teamProfileName').value='';$('teamProfileRole').value='';$('teamProfileEmail').value='';openLayer('team-profile');setTimeout(()=>$('teamProfileName').focus(),80)}
async function saveTeamProfile(){const name=$('teamProfileName').value.trim();if(!name){toast('Informe o nome do usuário');$('teamProfileName').focus();return}try{const created=await api('/api/team-profiles',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,role:$('teamProfileRole').value.trim(),email:$('teamProfileEmail').value.trim()})});activeTeamProfileId=created.id;closeLayers();await loadTeamProfiles();navigateToSection('carteiras');toast(`Perfil “${created.name}” criado`)}catch(error){toast(error.message)}}
async function deleteTeamProfile(profileId){if(!confirm('Excluir este perfil e a carteira de leads dele?'))return;try{await api('/api/team-profiles/'+encodeURIComponent(profileId),{method:'DELETE'});if(activeTeamProfileId===profileId)activeTeamProfileId='';await loadTeamProfiles();toast('Perfil individual excluído')}catch(error){toast(error.message)}}
function setPeriodFields(days){const end=latestReference?new Date(latestReference+'T12:00:00'):new Date(),start=new Date(end);$('fim').value=end.toISOString().slice(0,10);if(days==='all')$('inicio').value='';else{start.setDate(end.getDate()-Number(days));$('inicio').value=start.toISOString().slice(0,10)}document.querySelectorAll('[data-days]').forEach(button=>button.classList.toggle('active',button.dataset.days==days))}
function setPeriod(days){setPeriodFields(days);markCustom();page=1;return load()}
function openLayer(name){closeLayers();$('overlay').classList.add('open');if(name==='detail')$('detailDrawer').classList.add('open');if(name==='import')$('importModal').classList.add('open');if(name==='profile')$('profileModal').classList.add('open');document.body.classList.add('modal-open')}
function closeLayers(){$('overlay').classList.remove('open');$('detailDrawer').classList.remove('open');$('importModal').classList.remove('open');$('profileModal').classList.remove('open');document.body.classList.remove('modal-open')}
function setSidebar(open){$('sidebar').classList.toggle('open',open);document.body.classList.toggle('sidebar-open',open)}
const viewNames={dashboard:'VISÃO GERAL',oportunidades:'ALTO POTENCIAL',perfis:'EQUIPE COMERCIAL',carteiras:'CARTEIRAS DE LEADS',segmentacoes:'SEGMENTAÇÕES SALVAS',pipeline:'FUNIL COMERCIAL',empresas:'EMPRESAS RECENTES',analises:'INTELIGÊNCIA CNAE',monitor:'MONITOR DIÁRIO'};
const viewGuides={
  analises:{icon:'⌁',eyebrow:'DESCOBRIR O MERCADO',title:'Inteligência CNAE',description:'Entenda quais atividades e municípios concentram as novas aberturas de MEI.',purpose:'Compare CNAEs, períodos e regiões; clique em um resultado para abrir as empresas relacionadas.'},
  empresas:{icon:'◇',eyebrow:'PESQUISAR E FILTRAR',title:'Empresas recentes',description:'Consulte a base real e refine a lista por atividade, território, contato e potencial.',purpose:'Aplique filtros, abra uma empresa e encaminhe o lead para a carteira de um vendedor.'},
  oportunidades:{icon:'✦',eyebrow:'PRIORIZAR A ABORDAGEM',title:'Alto potencial',description:'Visualize primeiro os leads mais recentes, ativos e completos para prospecção.',purpose:'Abra um lead prioritário, confira os dados públicos e adicione-o à carteira responsável.'},
  perfis:{icon:'◎',eyebrow:'ORGANIZAR A EQUIPE',title:'Perfis individuais',description:'Cada vendedor trabalha com uma carteira e um histórico comercial independentes.',purpose:'Crie ou selecione um perfil para separar favoritos, etapas, estratégias e observações.'},
  carteiras:{icon:'▣',eyebrow:'TRABALHAR OS LEADS',title:'Carteiras por perfil',description:'Centralize as oportunidades escolhidas para cada integrante da equipe comercial.',purpose:'Atualize etapas, registre estratégias e exporte somente os leads relevantes deste perfil.'},
  pipeline:{icon:'◫',eyebrow:'ACOMPANHAR RESULTADOS',title:'Funil comercial',description:'Veja como as oportunidades avançam da triagem inicial até a conversão.',purpose:'Clique em uma etapa para filtrar suas empresas e identificar onde o processo está parado.'},
  segmentacoes:{icon:'◈',eyebrow:'REUTILIZAR RECORTES',title:'Segmentações salvas',description:'Guarde combinações de CNAE, período, região, contato e potencial.',purpose:'Aplique um recorte salvo para repetir a mesma pesquisa sem configurar todos os filtros novamente.'},
  monitor:{icon:'↻',eyebrow:'MANTER A BASE ATUALIZADA',title:'Monitor diário',description:'Acompanhe sincronização, validação Serpro e descoberta incremental de novos CNPJs.',purpose:'Verifique a situação das fontes e execute uma rodada manual quando precisar atualizar a base.'}
};
function updateWorkspaceGuide(id){const guide=viewGuides[id];if(!guide)return;const values={workspaceIcon:guide.icon,workspaceEyebrow:guide.eyebrow,workspaceTitle:guide.title,workspaceDescription:guide.description,workspacePurpose:guide.purpose};Object.entries(values).forEach(([elementId,value])=>{const element=$(elementId);if(element)element.textContent=value})}
function navigateToSection(id,link){const target=$(id);if(!target)return;document.body.dataset.view=id;updateWorkspaceGuide(id);const hash='#'+id;if(location.hash!==hash){if(link)history.pushState({radarView:id},'',hash);else history.replaceState({radarView:id},'',hash)}window.scrollTo({top:0,behavior:'auto'});document.querySelectorAll('.primary-navigation a').forEach(item=>{const active=item.getAttribute('href')===hash;item.classList.toggle('active',active);if(active)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current')});target.classList.remove('view-entering');requestAnimationFrame(()=>target.classList.add('view-entering'));const crumb=document.querySelector('.crumb');if(crumb)crumb.innerHTML=`<span class="crumb-signal"></span> CENTRAL DE INTELIGÊNCIA <span>/</span> ${viewNames[id]||'VISÃO GERAL'}`;document.title=`${viewNames[id]||'Visão geral'} · Radar CNPJ RS`;setSidebar(false)}
async function pollSync(){clearTimeout(syncPollTimer);let delay=document.hidden?120000:60000;try{const s=await api('/api/sync'),running=['starting','running'].includes(s.status),download=s.total_bytes?Math.round(s.baixados/s.total_bytes*70):0,progress=Math.min(100,Math.max(Math.round(s.progresso||0),download));delay=running?2500:delay;$('syncProgress').style.width=progress+'%';$('syncPercent').textContent=progress+'%';$('syncPhase').textContent=s.fase||'Aguardando sincronização';$('syncMessage').textContent=s.mensagem||'O Radar baixa as tabelas nacionais e mantém somente os novos CNPJs do Rio Grande do Sul.';$('importModal').classList.toggle('busy',running);$('syncStart').textContent=running?'Sincronizando…':s.status==='complete'?'Sincronizar novamente':'Sincronizar agora';const first=running&&!(s.local&&s.local.competencia);$('sourceBanner').hidden=!first;if(first){$('sourceTitle').textContent='Preparando a base oficial '+(s.competencia||'');$('sourceDetail').textContent=`${s.fase} · ${formatBytes(s.baixados)} de ${formatBytes(s.total_bytes)}.`;$('sourceProgress').textContent=progress+'%'}if(running)$('sideFresh').textContent=`${s.fase} · ${formatBytes(s.baixados)}`;if(s.status==='complete'&&lastSyncStatus&&lastSyncStatus!==s.status){allOptionsLoaded=false;load();toast(`${Number(s.importados||0).toLocaleString('pt-BR')} registros atualizados`)}if(s.status==='error'&&lastSyncStatus!==s.status)toast('Falha na sincronização: '+s.mensagem,6000);lastSyncStatus=s.status}catch(error){console.warn(error)}finally{syncPollTimer=setTimeout(pollSync,delay)}}
function formatBytes(n){if(!n)return '0 MB';return n>=1073741824?(n/1073741824).toFixed(1)+' GB':(n/1048576).toFixed(0)+' MB'}
async function pollMonitor(){clearTimeout(monitorPollTimer);let delay=document.hidden?120000:60000;try{const s=await api('/api/monitor'),running=['starting','running'].includes(s.status);delay=running?2500:delay;$('monitorValidationStatus').textContent=s.configurado?(running?'Consultando base oficial':'Integração pronta'):'Configuração pendente';$('monitorConfigured').classList.toggle('ready',s.configurado);$('monitorCredentialText').textContent=s.configurado?`Ambiente de ${s.ambiente}; execução diária às ${String(s.hora_execucao).padStart(2,'0')}h.`:`Faltam: ${(s.pendencias_configuracao||[]).join(', ')}.`;$('monitorDiscoveryStatus').textContent=s.fonte_descoberta_configurada?'Feed automático conectado':'Base mensal + Serpro';$('monitorDiscoveryText').textContent=s.fonte_descoberta_configurada?'Novos números do feed serão validados e incorporados automaticamente.':'A revalidação diária está pronta; a descoberta no mesmo dia aguarda um feed incremental.';$('monitorToday').textContent=Number(s.validados_hoje||0).toLocaleString('pt-BR');$('monitorQueue').textContent=Number(s.fila||0).toLocaleString('pt-BR');$('monitorLimit').textContent=Number(s.limite_diario||0).toLocaleString('pt-BR');$('monitorRun').disabled=running;$('monitorRun').textContent=running?`Validando ${s.processados||0}…`:'Executar agora ↻';const last=s.ultima_execucao;$('monitorLastRun').textContent=last?`${fmtDateTime(last.started_at)} · ${last.status}`:'Nenhuma execução registrada';$('monitorMessage').textContent=s.mensagem||(last?.message)||'O agendamento será ativado assim que as credenciais da Serpro forem configuradas.';if(['complete','partial'].includes(s.status)&&lastMonitorStatus==='running'){load();toast('Monitoramento diário concluído')}lastMonitorStatus=s.status}catch(error){console.warn(error)}finally{monitorPollTimer=setTimeout(pollMonitor,delay)}}
